import{_ as r,o as t,c as o,ag as a}from"./chunks/framework.D5hoimZQ.js";const m=JSON.parse('{"title":"🔬 科学快报 | 2026年7月24日（第 ? 期 · 事后重建版）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/reconstructed/2026-07-24.md","filePath":"science-log/src/reconstructed/2026-07-24.md"}'),n={name:"science-log/src/reconstructed/2026-07-24.md"};function s(c,e,i,d,g,l){return t(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="🔬-科学快报-2026年7月24日-第-期-·-事后重建版" tabindex="-1">🔬 科学快报 | 2026年7月24日（第 ? 期 · 事后重建版） <a class="header-anchor" href="#🔬-科学快报-2026年7月24日-第-期-·-事后重建版" aria-label="Permalink to &quot;🔬 科学快报 | 2026年7月24日（第 ? 期 · 事后重建版）&quot;">​</a></h1><blockquote><p>⚠️ <strong>事后重建版</strong>：本文件<strong>不是</strong>当日发布原文。由 2026-11-07 依 arXiv / CrossRef <strong>按发布日期回溯检索</strong>生成，选题与排序均为事后判定，<strong>不代表历史原貌</strong>。 检索说明：2026-07-24 为<strong>周五</strong>。CrossRef 按 <code>from-pub-date=until-pub-date=2026-07-24</code> 检索：Nature（0028-0836）命中 6 条但<strong>研究论文 0 条</strong>（5 条为 d41586 新闻/Briefing，1 条为 Author Correction，均按要求丢弃）；Science 前缀（10.1126）命中 83 条（以 Science Advances 为主）；PNAS（0027-8424）命中 9 条。故科学 5 篇取自<strong>当日真实出版</strong>的 PNAS 2 篇 + Science Advances 3 篇。AI 5 篇严格取自 arXiv <code>submittedDate:[202607240000 TO 202607242359]</code> 的 cs.AI 真实条目（命中 40 篇）。 取证：CrossRef（Nature 0028-0836 / Science 10.1126 / PNAS 0027-8424）+ arXiv 日期区间 <code>[202607240000 TO 202607242359]</code>（cs.AI，40 条）+ CrossRef 摘要核验 ｜ 重建日：2026-11-07</p></blockquote><h2 id="🔬-科学前沿" tabindex="-1">🔬 科学前沿 <a class="header-anchor" href="#🔬-科学前沿" aria-label="Permalink to &quot;🔬 科学前沿&quot;">​</a></h2><h3 id="🧲-弱到测不到的「倾斜磁矩」-被太赫兹辐射直接读出来" tabindex="-1">🧲 弱到测不到的「倾斜磁矩」，被太赫兹辐射直接读出来 <a class="header-anchor" href="#🧲-弱到测不到的「倾斜磁矩」-被太赫兹辐射直接读出来" aria-label="Permalink to &quot;🧲 弱到测不到的「倾斜磁矩」，被太赫兹辐射直接读出来&quot;">​</a></h3><p><strong>Resolving weak moments in canted antiferromagnets via time-domain terahertz emission spectroscopy</strong><em>PNAS（2026）</em></p><p>倾斜反铁磁体（canted antiferromagnet）身上有个尴尬的组合：反铁磁序带来太赫兹级的超快响应，而自旋倾斜带来的净磁矩小到常规磁光与电学手段在薄膜里几乎测不出来。作者（Sha、Guan、Wang、Li 等 12 人）改用<strong>时域太赫兹发射光谱</strong>做非接触探针，模型体系是外延 TmFeO₃/Pt 异质结。结果很干净：发射的太赫兹信号<strong>直接跟随倾斜的 Fe³⁺ 净磁矩取向</strong>，因此可以实时追踪该磁矩在自旋重取向转变（spin reorientation transition）中的连续转动。更反常的是，该体系的太赫兹磁滞<strong>极性与常规铁磁体/Pt 体系相反</strong>，指向一种非常规的界面磁构型。这把太赫兹发射确立为解析倾斜反铁磁薄膜、超薄膜超快磁响应的实用工具——也就是给&quot;几乎无净磁矩&quot;的反铁磁自旋电子学提供了一台可用的读表。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2603194123" target="_blank" rel="noreferrer">10.1073/pnas.2603194123</a></p><h3 id="☁️-7000-次高分辨率模拟-太平洋低云把变暖又放大了一档" tabindex="-1">☁️ 7000 次高分辨率模拟：太平洋低云把变暖又放大了一档 <a class="header-anchor" href="#☁️-7000-次高分辨率模拟-太平洋低云把变暖又放大了一档" aria-label="Permalink to &quot;☁️ 7000 次高分辨率模拟：太平洋低云把变暖又放大了一档&quot;">​</a></h3><p><strong>High-resolution simulations reveal positive global warming feedback from Pacific low clouds</strong><em>Science Advances（2026）</em></p><p>海洋低云反馈是气候预估里最大的不确定源之一，因为云的量与亮度对边界层结构极为敏感，而粗网格模式参数化不了。作者（Chammas、Wang、Schneider、Carver、Shen、Parker 等 10 人）做了 <strong>7,083 次热带太平洋低云的高分辨率模拟</strong>，把「海表增温」与「CO₂ 直接效应」两个因素拆开。结果是：仅海表增温就给出 <strong>+0.14 W m⁻² K⁻¹ 的正低云反馈</strong>，翻倍 CO₂ 时基本不变；但到 <strong>四倍 CO₂</strong> 时，总云辐射响应跃升到 <strong>+0.43 W m⁻² K⁻¹</strong>，暴露出强非线性。机制是：增温通过逆温层增强与下沉减弱抬高了云中含水量（增亮），同时云量下降；而高 CO₂ 的快速调整抵消了这层「保护性增厚」，于是云量减少不再被亮度增加抵消。结论直接冲击「气候敏感度是常数」的默认假设——它更依赖气候状态本身。</p><p>📎 DOI: <a href="https://doi.org/10.1126/sciadv.aec8488" target="_blank" rel="noreferrer">10.1126/sciadv.aec8488</a></p>',11)])])}const h=r(n,[["render",s]]);export{m as __pageData,h as default};
